#include "global.h"
#include "event_data.h"
#include "fieldmap.h"
#include "heal_location.h"
#include "kanto_time_skip.h"
#include "overworld.h"
#include "constants/heal_locations.h"
#include "constants/maps.h"

// Pokémon World: Kanto's time skip (see include/kanto_time_skip.h).
//
// The FireRed -> Heart & Soul map table is generated by tools/pokemon_world/gen_kanto_time_skip.py.
// A warp into a FireRed map is then placed like this:
//  - to a FireRed heal location (Fly, whiteout, Teleport, the debug town warps): that town's
//    heal location in the later Kanto;
//  - through a door (warp id): the later map's door that leads to the same place (that door's
//    FireRed destination, matched through the table), the closest one if there are several,
//    else the door at about the same spot (positions scaled to the later map's size);
//  - to a position (escape rope, Dig, scripted warps): the matching door if the position is next
//    to a FireRed door or cave mouth, else the later map's heal location, else the matching door
//    of the nearest FireRed warp;
//  - no position (map centre): the later map's centre.
// Map connections (walking from one map into the next) aren't changed: after the switch the
// player is never in FireRed's Kanto to walk out of it.

struct KantoTimeSkipMap
{
    u8 frGroup, frNum, hnsGroup, hnsNum;
};

#include "data/kanto_time_skip.h"

#define NEAR_WARP_DIST 2

bool32 KantoTimeSkip_IsActive(void)
{
    return FlagGet(FLAG_PW_KANTO_TIME_SKIP);
}

static const struct KantoTimeSkipMap *FindMap(u32 group, u32 num)
{
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sKantoTimeSkipMaps); i++)
    {
        if (sKantoTimeSkipMaps[i].frGroup == group && sKantoTimeSkipMaps[i].frNum == num)
            return &sKantoTimeSkipMaps[i];
    }
    return NULL;
}

static const struct MapHeader *GetHeader(u32 group, u32 num)
{
    return Overworld_GetMapHeaderByGroupAndId(group, num);
}

static u32 Distance(s32 x1, s32 y1, s32 x2, s32 y2)
{
    return abs(x1 - x2) + abs(y1 - y2);
}

// The later map's warp that matches FireRed's warp number frWarpId: one leading to the same
// place, else the one at about the same spot. -1 if the later map has no warps.
static s32 MatchWarp(const struct MapHeader *fr, u32 frWarpId, const struct MapHeader *hns)
{
    const struct WarpEvent *fw = &fr->events->warps[frWarpId];
    u32 destGroup = fw->mapGroup, destNum = fw->mapNum;
    const struct KantoTimeSkipMap *dest = FindMap(destGroup, destNum);
    s32 x, y, i, best = -1;
    u32 bestDist = 0xFFFF, pass;

    if (dest != NULL)
    {
        destGroup = dest->hnsGroup;
        destNum = dest->hnsNum;
    }
    // FireRed's spot, scaled to the later map's size
    x = fw->x * hns->mapLayout->width / max(fr->mapLayout->width, 1);
    y = fw->y * hns->mapLayout->height / max(fr->mapLayout->height, 1);

    for (pass = 0; pass < 2 && best < 0; pass++)
    {
        for (i = 0; i < hns->events->warpCount; i++)
        {
            const struct WarpEvent *hw = &hns->events->warps[i];
            u32 dist;

            if (pass == 0 && !(hw->mapGroup == destGroup && hw->mapNum == destNum))
                continue;
            dist = Distance(hw->x, hw->y, x, y);
            if (dist < bestDist)
            {
                bestDist = dist;
                best = i;
            }
        }
    }
    return best;
}

static bool32 RedirectToHealLocation(struct WarpData *warp)
{
    u32 i, fr = GetHealLocationIndexByWarpData(warp);
    const struct HealLocation *heal;

    if (fr == HEAL_LOCATION_NONE)
        return FALSE;
    for (i = 0; i < ARRAY_COUNT(sKantoTimeSkipHeals); i++)
    {
        if (sKantoTimeSkipHeals[i][0] == fr && (heal = GetHealLocation(sKantoTimeSkipHeals[i][1])) != NULL)
        {
            warp->mapGroup = heal->mapGroup;
            warp->mapNum = heal->mapNum;
            warp->warpId = WARP_ID_NONE;
            warp->x = heal->x;
            warp->y = heal->y;
            return TRUE;
        }
    }
    return FALSE;
}

bool32 KantoTimeSkip_RedirectWarp(struct WarpData *warp)
{
    const struct KantoTimeSkipMap *map;
    const struct MapHeader *fr, *hns;
    const struct HealLocation *heal;
    s32 i, nearest = -1, hnsWarp = -1;
    u32 nearestDist = 0xFFFF;

    if (!KantoTimeSkip_IsActive() || (map = FindMap((u8)warp->mapGroup, (u8)warp->mapNum)) == NULL)
        return FALSE;

    fr = GetHeader(map->frGroup, map->frNum);
    hns = GetHeader(map->hnsGroup, map->hnsNum);

    if (warp->warpId >= 0 && warp->warpId < fr->events->warpCount)
    {
        hnsWarp = MatchWarp(fr, warp->warpId, hns);
    }
    else if (warp->x >= 0 && warp->y >= 0)
    {
        if (RedirectToHealLocation(warp))
            return TRUE;
        for (i = 0; i < fr->events->warpCount; i++)
        {
            u32 dist = Distance(fr->events->warps[i].x, fr->events->warps[i].y, warp->x, warp->y);
            if (dist < nearestDist)
            {
                nearestDist = dist;
                nearest = i;
            }
        }
        heal = GetHealLocationByMap(map->hnsGroup, map->hnsNum);
        if (nearest >= 0 && (nearestDist <= NEAR_WARP_DIST || heal == NULL))
        {
            hnsWarp = MatchWarp(fr, nearest, hns);
        }
        else if (heal != NULL)
        {
            warp->mapGroup = heal->mapGroup;
            warp->mapNum = heal->mapNum;
            warp->warpId = WARP_ID_NONE;
            warp->x = heal->x;
            warp->y = heal->y;
            return TRUE;
        }
    }

    warp->mapGroup = map->hnsGroup;
    warp->mapNum = map->hnsNum;
    if (hnsWarp >= 0)
    {
        warp->warpId = hnsWarp;
        warp->x = hns->events->warps[hnsWarp].x;
        warp->y = hns->events->warps[hnsWarp].y;
    }
    else
    {
        // no warp to match: keep the position if it fits, else the map's centre
        warp->warpId = WARP_ID_NONE;
        if (warp->x >= hns->mapLayout->width || warp->y >= hns->mapLayout->height)
            warp->x = warp->y = -1;
    }
    return TRUE;
}

void KantoTimeSkip_FixSavedWarps(void)
{
    KantoTimeSkip_RedirectWarp(&gSaveBlock1Ptr->lastHealLocation);
    KantoTimeSkip_RedirectWarp(&gSaveBlock1Ptr->escapeWarp);
    KantoTimeSkip_RedirectWarp(&gSaveBlock1Ptr->continueGameWarp);
}

void KantoTimeSkip_Native_FixSavedWarps(struct ScriptContext *ctx)
{
    KantoTimeSkip_FixSavedWarps();
}
